example_item.example_item_data:
f = uifigure();
page = ['<html><body><p id="out">waiting</p><script>', ...
  'function setup(h) {', ...
  '  h.addEventListener("tick", function (evt) {', ...
  '    document.getElementById("out").textContent = evt.Data.count;', ...
  '  });', ...
  '}</script></body></html>'];
h = uihtml(f, 'Position', [10 10 300 100], 'HTMLSource', page);
for k = 1:5
  sendEventToHTMLSource(h, 'tick', struct('count', k));
  pause(0.5);
end
